bool ImportDxfGraphic(SvStream & rStream, Graphic & rGraphic)
{
    DXFRepresentation aDXF;
    DXF2GDIMetaFile aConverter;
    GDIMetaFile aMTF;

    if ( !aDXF.Read( rStream ) )
        return false;
    if ( !aConverter.Convert( aDXF, aMTF, 60, 100 ) )
        return false;
    rGraphic = Graphic(aMTF);

    return true;
}
